ALTER TABLE dispatch_jobs ADD COLUMN current_attempt_id INTEGER;
ALTER TABLE dispatch_jobs ADD COLUMN retry_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE dispatch_jobs ADD COLUMN queue_rank INTEGER NOT NULL DEFAULT 3;
ALTER TABLE dispatch_jobs ADD COLUMN dispatch_order REAL NOT NULL DEFAULT 0;
ALTER TABLE accounts ADD COLUMN connection_retry_at REAL NOT NULL DEFAULT 0;
ALTER TABLE accounts ADD COLUMN connection_failures INTEGER NOT NULL DEFAULT 0;
UPDATE dispatch_jobs SET current_attempt_id=(SELECT max(id) FROM message_attempts WHERE job_id=dispatch_jobs.id);
CREATE TABLE queue_counters (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO queue_counters SELECT 'pending',count(*) FROM dispatch_jobs WHERE status='PENDING';
CREATE TRIGGER job_pending_insert AFTER INSERT ON dispatch_jobs WHEN NEW.status='PENDING' BEGIN UPDATE queue_counters SET value=value+1 WHERE name='pending'; END;
CREATE TRIGGER job_pending_update AFTER UPDATE OF status ON dispatch_jobs WHEN OLD.status<>NEW.status BEGIN UPDATE queue_counters SET value=value+(NEW.status='PENDING')-(OLD.status='PENDING') WHERE name='pending'; END;
CREATE TRIGGER job_pending_delete AFTER DELETE ON dispatch_jobs WHEN OLD.status='PENDING' BEGIN UPDATE queue_counters SET value=value-1 WHERE name='pending'; END;
UPDATE dispatch_jobs SET queue_rank=CASE kind WHEN 'CHECK' THEN 0 WHEN 'JOIN' THEN 1 WHEN 'GREETING' THEN 2 ELSE 3 END;
CREATE INDEX job_ready_order ON dispatch_jobs(status,queue_rank,dispatch_order,id,planned_at);
CREATE INDEX job_pair_status ON dispatch_jobs(pair_id,status,chat_pool_id);
CREATE INDEX job_account_status ON dispatch_jobs(account_id,status,kind);
CREATE INDEX job_expiry ON dispatch_jobs(status,lease_until);
CREATE INDEX active_pair_chats ON pair_chats(pair_id,id) WHERE removed_at IS NULL;
CREATE INDEX pool_free_approved ON chat_pool(status,approved,id);
CREATE INDEX result_time ON message_results(confirmed_at,job_id);
CREATE INDEX attempt_time ON message_attempts(started_at,job_id,outcome);
CREATE INDEX audit_entity_time ON audit_events(campaign_id,pair_id,created_at);
CREATE INDEX outbox_ready ON notifications_outbox(status,next_attempt_at,priority,id);
CREATE INDEX action_expiry ON ui_actions(expires_at);
CREATE INDEX receipt_expiry ON admin_update_receipts(created_at);
CREATE TABLE service_diagnostics (id INTEGER PRIMARY KEY, component TEXT NOT NULL, error_code TEXT NOT NULL, created_at REAL NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE INDEX diagnostics_time ON service_diagnostics(created_at,id);
CREATE TRIGGER pair_account_distinct_insert BEFORE INSERT ON pairs WHEN NEW.account_a_id IS NOT NULL OR NEW.account_b_id IS NOT NULL BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM pairs p WHERE p.account_a_id IN (NEW.account_a_id,NEW.account_b_id) OR p.account_b_id IN (NEW.account_a_id,NEW.account_b_id)) THEN RAISE(ABORT,'account already paired') END; END;
CREATE TRIGGER pair_account_distinct_update BEFORE UPDATE OF account_a_id,account_b_id ON pairs BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM pairs p WHERE p.id<>NEW.id AND (p.account_a_id IN (NEW.account_a_id,NEW.account_b_id) OR p.account_b_id IN (NEW.account_a_id,NEW.account_b_id))) THEN RAISE(ABORT,'account already paired') END; END;
